CREATE TABLE "c_BillingAccount" ("id" BIGINT NOT NULL, "a_BillingAccount_balance" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Department" ("id" BIGINT NOT NULL, "a_Department_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Encounter" ("id" BIGINT NOT NULL, "a_Encounter_admit_time" TIMESTAMP NOT NULL, "a_Encounter_discharge_time" TIMESTAMP, "r_PatientEncounters_source_id" BIGINT, "r_PatientEncounters_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_PatientEncounters_source_dtype" IS NULL OR "r_PatientEncounters_source_dtype" IN ('Patient')), CHECK ((TRUE) OR "r_PatientEncounters_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_PatientEncounters_source_id" IS NOT NULL));
CREATE TABLE "c_InsurancePlan" ("id" BIGINT NOT NULL, "a_InsurancePlan_payer" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_LabOrder" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_LabOrder_specimen" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('LabOrder')));
CREATE TABLE "c_MedicationOrder" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_MedicationOrder_route" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('MedicationOrder')));
CREATE TABLE "c_OrderRequest" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_OrderRequest_priority" TEXT NOT NULL, "r_EncounterOrders_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('LabOrder','MedicationOrder','OrderRequest')), CHECK ((dtype IN ('LabOrder','MedicationOrder','OrderRequest')) OR "r_EncounterOrders_source_id" IS NULL), CHECK (NOT (dtype IN ('LabOrder','MedicationOrder','OrderRequest')) OR "r_EncounterOrders_source_id" IS NOT NULL));
CREATE TABLE "c_Person" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Patient_mrn" TEXT, "a_Person_name" TEXT, "a_Person_dob" DATE, "a_Provider_credential" TEXT, "r_DepartmentProviders_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Patient','Person','Provider')), CHECK ((dtype IN ('Patient')) OR "a_Patient_mrn" IS NULL), CHECK (NOT (dtype IN ('Patient')) OR "a_Patient_mrn" IS NOT NULL), CHECK ((dtype IN ('Patient','Person','Provider')) OR "a_Person_name" IS NULL), CHECK (NOT (dtype IN ('Patient','Person','Provider')) OR "a_Person_name" IS NOT NULL), CHECK ((dtype IN ('Patient','Person','Provider')) OR "a_Person_dob" IS NULL), CHECK (NOT (dtype IN ('Patient','Person','Provider')) OR "a_Person_dob" IS NOT NULL), CHECK ((dtype IN ('Provider')) OR "a_Provider_credential" IS NULL), CHECK (NOT (dtype IN ('Provider')) OR "a_Provider_credential" IS NOT NULL), CHECK ((dtype IN ('Provider')) OR "r_DepartmentProviders_source_id" IS NULL), CHECK (NOT (dtype IN ('Provider')) OR "r_DepartmentProviders_source_id" IS NOT NULL));
CREATE TABLE "c_Result" ("id" BIGINT NOT NULL, "a_Result_value_text" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_OrderResults" ("r_OrderResults_source_id" BIGINT NOT NULL, "r_OrderResults_source_dtype" TEXT NOT NULL, "r_OrderResults_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_OrderResults_source_id", "r_OrderResults_target_id"), UNIQUE ("r_OrderResults_target_id"), CHECK ("r_OrderResults_source_dtype" IS NULL OR "r_OrderResults_source_dtype" IN ('LabOrder','MedicationOrder','OrderRequest')));
CREATE TABLE "l_PatientBilling" ("r_PatientBilling_source_id" BIGINT NOT NULL, "r_PatientBilling_source_dtype" TEXT NOT NULL, "r_PatientBilling_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PatientBilling_source_id", "r_PatientBilling_target_id"), UNIQUE ("r_PatientBilling_target_id"), UNIQUE ("r_PatientBilling_source_id"), CHECK ("r_PatientBilling_source_dtype" IS NULL OR "r_PatientBilling_source_dtype" IN ('Patient')));
CREATE TABLE "l_PatientPlans" ("r_PatientPlans_source_id" BIGINT NOT NULL, "r_PatientPlans_source_dtype" TEXT NOT NULL, "r_PatientPlans_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PatientPlans_source_id", "r_PatientPlans_target_id"), CHECK ("r_PatientPlans_source_dtype" IS NULL OR "r_PatientPlans_source_dtype" IN ('Patient')));
CREATE TABLE "l_ProviderEncounters" ("r_ProviderEncounters_source_id" BIGINT NOT NULL, "r_ProviderEncounters_source_dtype" TEXT NOT NULL, "r_ProviderEncounters_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_ProviderEncounters_source_id", "r_ProviderEncounters_target_id"), CHECK ("r_ProviderEncounters_source_dtype" IS NULL OR "r_ProviderEncounters_source_dtype" IN ('Provider')));
ALTER TABLE "c_Encounter" ADD CONSTRAINT "fk_c_Encounter_0" FOREIGN KEY ("r_PatientEncounters_source_id", "r_PatientEncounters_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_LabOrder" ADD CONSTRAINT "fk_c_LabOrder_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_OrderRequest" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_MedicationOrder" ADD CONSTRAINT "fk_c_MedicationOrder_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_OrderRequest" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_OrderRequest" ADD CONSTRAINT "fk_c_OrderRequest_0" FOREIGN KEY ("r_EncounterOrders_source_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Person" ADD CONSTRAINT "fk_c_Person_0" FOREIGN KEY ("r_DepartmentProviders_source_id") REFERENCES "c_Department" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrderResults" ADD CONSTRAINT "fk_l_OrderResults_0" FOREIGN KEY ("r_OrderResults_source_id", "r_OrderResults_source_dtype") REFERENCES "c_OrderRequest" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrderResults" ADD CONSTRAINT "fk_l_OrderResults_1" FOREIGN KEY ("r_OrderResults_target_id") REFERENCES "c_Result" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientBilling" ADD CONSTRAINT "fk_l_PatientBilling_0" FOREIGN KEY ("r_PatientBilling_source_id", "r_PatientBilling_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientBilling" ADD CONSTRAINT "fk_l_PatientBilling_1" FOREIGN KEY ("r_PatientBilling_target_id") REFERENCES "c_BillingAccount" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientPlans" ADD CONSTRAINT "fk_l_PatientPlans_0" FOREIGN KEY ("r_PatientPlans_source_id", "r_PatientPlans_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientPlans" ADD CONSTRAINT "fk_l_PatientPlans_1" FOREIGN KEY ("r_PatientPlans_target_id") REFERENCES "c_InsurancePlan" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProviderEncounters" ADD CONSTRAINT "fk_l_ProviderEncounters_0" FOREIGN KEY ("r_ProviderEncounters_source_id", "r_ProviderEncounters_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProviderEncounters" ADD CONSTRAINT "fk_l_ProviderEncounters_1" FOREIGN KEY ("r_ProviderEncounters_target_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_OrderResults"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Result" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_OrderResults" l WHERE l."r_OrderResults_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: OrderResults'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_OrderResults_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Result" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_OrderResults"();
CREATE CONSTRAINT TRIGGER "ct_OrderResults_link" AFTER INSERT OR UPDATE OR DELETE ON "l_OrderResults" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_OrderResults"();
CREATE FUNCTION "require_PatientBilling"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_BillingAccount" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_PatientBilling" l WHERE l."r_PatientBilling_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: PatientBilling'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_PatientBilling_target" AFTER INSERT OR UPDATE OR DELETE ON "c_BillingAccount" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_PatientBilling"();
CREATE CONSTRAINT TRIGGER "ct_PatientBilling_link" AFTER INSERT OR UPDATE OR DELETE ON "l_PatientBilling" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_PatientBilling"();